	it("lists review comments without a since filter", async () => {
		const { client, pulls } = setup();
		pulls.listReviewComments.mockResolvedValueOnce({ data: page(2, 0) });
		await expect(client.listReviewComments(9)).resolves.toHaveLength(2);
		expect(pulls.listReviewComments).toHaveBeenCalledWith({
			owner: "o",
			repo: "r",
			pull_number: 9,
			per_page: 100,
			page: 1,
		});
	});
});

describe("isForkPullRequest", () => {
	it("tells a pull request from a fork by its head repository", () => {
		const pr = (head: string) => ({
			pull_request: {
				head: { repo: { full_name: head } },
				base: { repo: { full_name: "o/r" } },
			},
		});
		expect(isForkPullRequest(pr("fork/r"))).toBe(true);
		expect(isForkPullRequest(pr("o/r"))).toBe(false);
		expect(isForkPullRequest({ issue: { number: 1 } })).toBe(false);
	});
});
